import ee, sys
from datetime import datetime, timedelta

try:
    ee.Initialize(project='earthsense-436113')
except Exception as e:
    print(f"Initialization error: {str(e)}")
    print("D")
    sys.exit(0)

# 1. Geometry & Time Definitions
aoi = ee.Geometry.Rectangle([7.5, 54.3, 15.3, 58.0])  # Denmark + Bornholm bbox

def window(date_str, pad=7):
    dt = datetime.strptime(date_str, "%Y-%m-%d")
    start = (dt - timedelta(days=pad)).strftime("%Y-%m-%d")
    end = (dt + timedelta(days=pad+1)).strftime("%Y-%m-%d")  # end exclusive
    return start, end

# Land mask from JRC Global Surface Water (non-water: occurrence < 50%)
gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence')
landmask = gsw.lt(50)

# 2. Masking functions
def mask_s2_sr(img):
    qa = img.select('QA60')
    cloud = qa.bitwiseAnd(1 << 10).eq(0)
    cirrus = qa.bitwiseAnd(1 << 11).eq(0)
    mask = cloud.And(cirrus)
    scaled = img.updateMask(mask).select(['B4','B8']).divide(10000)
    return scaled.rename(['red','nir']).copyProperties(img, ['system:time_start','CLOUDY_PIXEL_PERCENTAGE'])

def mask_l8_l2(img):
    qa = img.select('QA_PIXEL')
    cloud = qa.bitwiseAnd(1 << 3).eq(0)
    cloudShadow = qa.bitwiseAnd(1 << 4).eq(0)
    snow = qa.bitwiseAnd(1 << 5).eq(0)
    dilated = qa.bitwiseAnd(1 << 1).eq(0)
    water = qa.bitwiseAnd(1 << 7).eq(0)
    mask = cloud.And(cloudShadow).And(snow).And(dilated).And(water)
    red = img.select('SR_B4').multiply(0.0000275).add(-0.2)
    nir = img.select('SR_B5').multiply(0.0000275).add(-0.2)
    return ee.Image.cat([red, nir]).updateMask(mask).rename(['red','nir']).copyProperties(img, ['system:time_start','CLOUD_COVER'])

def annotate_stats(img, scale_m=3000):
    ndvi = img.normalizedDifference(['nir','red']).rename('NDVI').updateMask(landmask)
    stats = ndvi.reduceRegion(
        reducer=ee.Reducer.mean().combine(reducer2=ee.Reducer.count(), sharedInputs=True),
        geometry=aoi, scale=scale_m, maxPixels=1e9
    )
    # Keys: NDVI_mean, NDVI_count
    return img.set({
        'ndvi_mean': stats.get('NDVI_mean'),
        'valid_count': stats.get('NDVI_count')
    })

def pick_best_image(col, limit_n=25, s2=True):
    # Limit images to reduce load, prioritizing least-cloudy
    if s2:
        col_sorted = col.sort('CLOUDY_PIXEL_PERCENTAGE').limit(limit_n)
    else:
        # Landsat 8 L2 often has CLOUD_COVER; if missing, sorting still works
        col_sorted = col.sort('CLOUD_COVER').limit(limit_n)
    annotated = col_sorted.map(annotate_stats)
    best = annotated.sort('valid_count', False).first()
    return best, col_sorted.size()

def land_pixel_count(scale_m=3000):
    return ee.Image(1).updateMask(landmask).reduceRegion(
        reducer=ee.Reducer.count(), geometry=aoi, scale=scale_m, maxPixels=1e9
    ).get('constant')

def stats_for_period(date_str):
    start, end = window(date_str, pad=7)
    scale_m = 3000

    # Sentinel-2 SR (harmonized)
    s2 = (ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
          .filterBounds(aoi)
          .filterDate(start, end)
          .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
          .map(mask_s2_sr))

    s2_size = s2.size().getInfo()
    if s2_size and s2_size > 0:
        best_img, considered = pick_best_image(s2, limit_n=25, s2=True)
        mean_ndvi = ee.Number(best_img.get('ndvi_mean')).getInfo()
        valid = ee.Number(best_img.get('valid_count')).getInfo()
        if valid is None:
            valid = 0
        if valid == 0:
            # Fallback to Landsat 8 L2
            l8 = (ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                  .filterBounds(aoi)
                  .filterDate(start, end)
                  .map(mask_l8_l2))
            l8_size = l8.size().getInfo()
            if l8_size and l8_size > 0:
                best_img2, considered2 = pick_best_image(l8, limit_n=25, s2=False)
                mean_ndvi2 = ee.Number(best_img2.get('ndvi_mean')).getInfo()
                valid2 = ee.Number(best_img2.get('valid_count')).getInfo()
                if valid2 is None or valid2 == 0:
                    return {'status':'C2', 'sensor':'L8', 'imgs':l8_size, 'considered':int(considered2.getInfo())}
                if mean_ndvi2 is None or not (-1.0 <= mean_ndvi2 <= 1.0):
                    return {'status':'C3', 'sensor':'L8'}
                land_cnt = ee.Number(land_pixel_count(scale_m)).getInfo()
                return {'status':'OK','sensor':'L8','imgs':l8_size,'considered':int(considered2.getInfo()),
                        'valid':int(valid2),'land':int(land_cnt),'mean':float(mean_ndvi2)}
            else:
                return {'status':'C2', 'sensor':'S2', 'imgs':s2_size, 'considered':int(considered.getInfo())}
        # S2 valid
        if mean_ndvi is None or not (-1.0 <= mean_ndvi <= 1.0):
            return {'status':'C3', 'sensor':'S2'}
        land_cnt = ee.Number(land_pixel_count(scale_m)).getInfo()
        return {'status':'OK','sensor':'S2','imgs':s2_size,'considered':int(considered.getInfo()),
                'valid':int(valid),'land':int(land_cnt),'mean':float(mean_ndvi)}
    else:
        # Fallback to Landsat 8 L2 directly
        l8 = (ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
              .filterBounds(aoi)
              .filterDate(start, end)
              .map(mask_l8_l2))
        l8_size = l8.size().getInfo()
        if not l8_size or l8_size == 0:
            return {'status':'C1', 'sensor':None}
        best_img2, considered2 = pick_best_image(l8, limit_n=25, s2=False)
        mean_ndvi2 = ee.Number(best_img2.get('ndvi_mean')).getInfo()
        valid2 = ee.Number(best_img2.get('valid_count')).getInfo()
        if valid2 is None or valid2 == 0:
            return {'status':'C2', 'sensor':'L8', 'imgs':l8_size, 'considered':int(considered2.getInfo())}
        if mean_ndvi2 is None or not (-1.0 <= mean_ndvi2 <= 1.0):
            return {'status':'C3', 'sensor':'L8'}
        land_cnt = ee.Number(land_pixel_count(3000)).getInfo()
        return {'status':'OK','sensor':'L8','imgs':l8_size,'considered':int(considered2.getInfo()),
                'valid':int(valid2),'land':int(land_cnt),'mean':float(mean_ndvi2)}

# 3. Run for both dates
date_2017 = '2017-07-19'
date_2018 = '2018-07-24'

res17 = stats_for_period(date_2017)
res18 = stats_for_period(date_2018)

# 4. Handle error cases
if res17.get('status') == 'C1' or res18.get('status') == 'C1':
    print(f"2017 Status: {res17.get('status')}, 2018 Status: {res18.get('status')}")
    print("C1")
    sys.exit(0)
if res17.get('status') == 'C2' or res18.get('status') == 'C2':
    print(f"2017 Status: {res17.get('status')}, 2018 Status: {res18.get('status')}")
    print("C2")
    sys.exit(0)
if res17.get('status') == 'C3' or res18.get('status') == 'C3':
    print(f"2017 Status: {res17.get('status')}, 2018 Status: {res18.get('status')}")
    print("C3")
    sys.exit(0)
if res17.get('status') not in ['OK'] or res18.get('status') not in ['OK']:
    print(f"2017 Status: {res17.get('status')}, 2018 Status: {res18.get('status')}")
    print("D")
    sys.exit(0)

# 5. Evidence prints (concise, <=20 lines)
land_count = res17['land']  # same scale/geom
print(f"AOI land pixels (3km): {land_count}")
unmasked17 = 100.0 * (res17['valid'] / land_count)
unmasked18 = 100.0 * (res18['valid'] / land_count)
print(f"2017-07-19 (Sensor={res17['sensor']}), Images: {res17['imgs']}, Considered: {res17['considered']}, Valid: {res17['valid']}/{land_count} ({unmasked17:.1f}% unmasked), Mean NDVI: {res17['mean']:.3f}")
print(f"2018-07-24 (Sensor={res18['sensor']}), Images: {res18['imgs']}, Considered: {res18['considered']}, Valid: {res18['valid']}/{land_count} ({unmasked18:.1f}% unmasked), Mean NDVI: {res18['mean']:.3f}")

diff = res18['mean'] - res17['mean']
print(f"NDVI Δ (2018-2017): {diff:.3f} (negative means 'more brown' in 2018)")

# 6. Decision: lower NDVI in 2018 -> Yes (A), else No (B)
if diff < -0.01:
    print("A")
else:
    print("B")
